// Package llamacpp is the core backend: llama.cpp on CPU and GPU on every
// platform (SPEC §3).
//
// It binds libllama through purego, so the binary is built with CGO_ENABLED=0
// and cross-compiles from one runner. ggml compute backends (CPU variants,
// Vulkan, CUDA, Metal, …) are separate libraries in lib/ loaded at runtime; a
// missing one is skipped with a warning, never fatal.
//
// The binding (zz_generated.go) is generated by tools/bindgen from the
// headers of one pinned release tag. At startup the library's commit
// (ggml_commit) is checked against the commit the binary was built for, and
// a mismatch is refused with a message, because a C ABI drift between builds
// does not fail loudly — it corrupts memory.
//
// Every input is validated in Go before it reaches C: llama.cpp aborts the
// process on a failed assertion (GGML_ABORT) and on any C++ exception that
// escapes the C API, and neither can be caught from Go.
package llamacpp

import (
	"context"
	"errors"
	"fmt"
	"sort"
	"strings"
	"unsafe"

	"github.com/ebitengine/purego"

	"github.com/usunrise88/nanollm/internal/backend"
)

// Name is the registered backend name and the prefix of its device selectors.
const Name = "llamacpp"

// MinTag is the oldest llama.cpp release that can run the primary
// configuration: Gemma 4 MTP landed in ggml-org/llama.cpp#23398, and E2B/E4B
// drafter conversion was fixed in #24282, which shipped in b9568.
//
// The pinned tag (scripts/llama.cpp.tag) must be at or above it. A later tag
// is preferable — quantized-KV and memory-fitting bugs around MTP were fixed
// after it — but which one is decided by the golden tests, not here.
const MinTag = "b9568"

// PinnedTag and PinnedCommit are the llama.cpp release this binary was built
// for, stamped by the linker from scripts/llama.cpp.tag and
// scripts/llama.cpp.commit:
//
//	-X github.com/usunrise88/nanollm/internal/backend/llamacpp.PinnedTag=b…
//	-X github.com/usunrise88/nanollm/internal/backend/llamacpp.PinnedCommit=…
//
// An unstamped build (go test, go run) falls back to the release the
// binding was generated from, which is what it must match anyway.
var (
	PinnedTag    = bindingTag
	PinnedCommit = bindingCommit
)

func init() {
	backend.Register(Name, open)
}

type llamaBackend struct {
	lib *library
}

func open(libDir string) (backend.Backend, error) {
	l, err := loadLibrary(libDir)
	if err != nil {
		return nil, err
	}
	if err := checkCommit(l.commit, PinnedCommit); err != nil {
		return nil, err
	}
	if PinnedCommit != bindingCommit && checkCommit(PinnedCommit, bindingCommit) != nil {
		return nil, fmt.Errorf("this binary is stamped for llama.cpp %s but its binding was generated from %s; regenerate with tools/bindgen", PinnedCommit, bindingCommit)
	}
	if err := l.init(); err != nil {
		return nil, err
	}
	return &llamaBackend{lib: l}, nil
}

func (b *llamaBackend) Name() string { return Name }

// Version is the tag and the commit the library reports, e.g. "b11600
// (ace20f679)".
func (b *llamaBackend) Version() string {
	return fmt.Sprintf("%s (%s)", PinnedTag, b.lib.commit)
}

// Warnings lists backend libraries in lib/ that did not load, with the
// reason; `nanollm devices` prints them.
func (b *llamaBackend) Warnings() []string { return b.lib.warnings }

// CPUVariant is the ggml CPU library picked for this processor.
func (b *llamaBackend) CPUVariant() string { return b.lib.cpuVariant }

// Devices lists the ggml devices that can hold a model. Accelerator devices
// (BLAS, AMX) only assist the CPU backend and are not listed; an integrated
// GPU is a GPU on unified memory.
func (b *llamaBackend) Devices(context.Context) ([]backend.Device, error) {
	var out []backend.Device
	for i := uintptr(0); i < ggmlBackendDevCount(); i++ {
		dev := ggmlBackendDevGet(i)
		var props GgmlBackendDevProps
		ggmlBackendDevGetProps(dev, &props)
		d := backend.Device{
			Backend:     Name,
			ID:          strings.ToLower(cString(props.Name)),
			Name:        cString(props.Description),
			MemoryTotal: int64(props.MemoryTotal),
			MemoryFree:  int64(props.MemoryFree),
		}
		switch props.Type {
		case GgmlBackendDeviceTypeCpu:
			d.Type = backend.CPU
		case GgmlBackendDeviceTypeGpu:
			d.Type = backend.GPU
		case GgmlBackendDeviceTypeIgpu:
			d.Type = backend.GPU
			d.Unified = true
		default:
			continue
		}
		out = append(out, d)
	}
	sort.SliceStable(out, func(i, j int) bool { return out[i].Type == backend.CPU && out[j].Type != backend.CPU })
	return out, nil
}

// device finds a ggml device by selector: "cpu", "llamacpp:cpu",
// "vulkan0", "llamacpp:vulkan0". The CPU is returned as 0: llama.cpp places
// on the CPU whatever no device takes.
func (b *llamaBackend) device(sel string) (GgmlBackendDevice, bool, error) {
	id := strings.ToLower(strings.TrimPrefix(sel, Name+":"))
	if id == "" || id == "cpu" {
		return 0, true, nil
	}
	var have []string
	for i := uintptr(0); i < ggmlBackendDevCount(); i++ {
		dev := ggmlBackendDevGet(i)
		name := strings.ToLower(ggmlBackendDevName(dev))
		if name == id {
			switch ggmlBackendDevType(dev) {
			case GgmlBackendDeviceTypeGpu, GgmlBackendDeviceTypeIgpu:
				return dev, false, nil
			case GgmlBackendDeviceTypeCpu:
				return 0, true, nil
			}
		}
		have = append(have, Name+":"+name)
	}
	return 0, false, fmt.Errorf("no device %q; this machine has %s", sel, strings.Join(have, ", "))
}

func (b *llamaBackend) Close() error { return nil }

// cpuRepackBuft finds the CPU backend's repacked buffer type among its extra
// buffer types, which only the CPU backend library exports
// (ggml_backend_dev_get_extra_bufts, through the registry's proc address). A
// tensor overridden to it is repacked even with use_extra_bufts off, which is
// how a mode repacks the tensors it keeps hot and leaves the rest in the file's
// mapping (docs/STAGE2.md OPT-1).
func (b *llamaBackend) cpuRepackBuft() (GgmlBackendBufferType, error) {
	for i := uintptr(0); i < ggmlBackendDevCount(); i++ {
		dev := ggmlBackendDevGet(i)
		if ggmlBackendDevType(dev) != GgmlBackendDeviceTypeCpu {
			continue
		}
		p := ggmlBackendRegGetProcAddress(ggmlBackendDevBackendReg(dev), "ggml_backend_dev_get_extra_bufts")
		if p == 0 {
			return 0, errors.New("this CPU backend has no extra buffer types (no repacked weights)")
		}
		var extra func(GgmlBackendDevice) *GgmlBackendBufferType
		purego.RegisterFunc(&extra, p)
		arr := extra(dev)
		if arr == nil {
			break
		}
		for k := 0; k < 16; k++ {
			bt := *(*GgmlBackendBufferType)(unsafe.Add(unsafe.Pointer(arr), uintptr(k)*unsafe.Sizeof(*arr)))
			if bt == 0 {
				break
			}
			if strings.Contains(strings.ToUpper(ggmlBackendBuftName(bt)), "REPACK") {
				return bt, nil
			}
		}
	}
	return 0, errors.New("no repacked buffer type on this CPU")
}
